"""Core sequence CRDT (RGA - Replicated Growable Array) for collaborative text.

This is the conflict-resolution heart of the editor. Each character is a node
with a globally unique id (lamport counter, site id). Concurrent inserts at the
same position are ordered deterministically by id, so all replicas converge
without a central authority (unlike OT, no server-side transformation needed).

Rich-text formatting is stored as per-character marks with last-writer-wins
(LWW) resolution keyed by op id.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Dict, List, Optional, Set, Tuple, Union


@dataclass(frozen=True, order=True)
class OpId:
    """Globally unique, totally ordered operation id (lamport counter + site)."""

    counter: int
    site: str


@dataclass(frozen=True)
class InsertOp:
    id: OpId
    origin: Optional[OpId]  # id of the character to the left; None = doc start
    char: str


@dataclass(frozen=True)
class DeleteOp:
    id: OpId
    target: OpId


@dataclass(frozen=True)
class UndeleteOp:
    """Resurrects a tombstone (used by undo of a delete / redo of an insert)."""

    id: OpId
    target: OpId


@dataclass(frozen=True)
class FormatOp:
    id: OpId
    targets: Tuple[OpId, ...]
    mark: str  # e.g. "bold", "italic", "link"
    value: object


Op = Union[InsertOp, DeleteOp, UndeleteOp, FormatOp]


@dataclass
class Node:
    id: OpId
    origin: Optional[OpId]
    char: str
    deleted: bool = False
    # mark -> (value, op id that set it) for LWW resolution
    attrs: Dict[str, Tuple[object, OpId]] = field(default_factory=dict)


class Document:
    """One replica of the shared document."""

    def __init__(self, site: str):
        self.site = site
        self.clock = 0  # lamport clock
        self.nodes: List[Node] = []  # includes tombstones
        self._ids: Set[OpId] = set()  # ids of integrated character nodes
        self._applied: Set[OpId] = set()  # every op id ever applied (idempotency)
        self.pending: List[Op] = []  # causally-buffered ops awaiting deps

    # ------------------------------------------------------------------ ids
    def _next_id(self) -> OpId:
        self.clock += 1
        return OpId(self.clock, self.site)

    def _tick(self, op_id: OpId) -> None:
        self.clock = max(self.clock, op_id.counter)

    def _pos(self, op_id: OpId) -> Optional[int]:
        for i, n in enumerate(self.nodes):
            if n.id == op_id:
                return i
        return None

    def _node(self, op_id: OpId) -> Node:
        pos = self._pos(op_id)
        if pos is None:
            raise KeyError(op_id)
        return self.nodes[pos]

    # ------------------------------------------------------------- visibility
    @property
    def text(self) -> str:
        return "".join(n.char for n in self.nodes if not n.deleted)

    def __len__(self) -> int:
        return sum(1 for n in self.nodes if not n.deleted)

    def _visible_node_at(self, index: int) -> Node:
        count = 0
        for n in self.nodes:
            if not n.deleted:
                if count == index:
                    return n
                count += 1
        raise IndexError(index)

    def id_at(self, index: int) -> OpId:
        """Id of the visible character at a visible index."""
        return self._visible_node_at(index).id

    def anchor_index(self, anchor: Optional[OpId]) -> int:
        """Visible index just after `anchor` (None = doc start).

        Used for cursors and comments: anchors survive remote edits because
        they reference immutable ids, not offsets. If the anchor char was
        deleted, this resolves to where the char used to be.
        """
        if anchor is None:
            return 0
        count = 0
        for n in self.nodes:
            if not n.deleted:
                count += 1
                if n.id == anchor:
                    return count
            elif n.id == anchor:
                return count
        raise KeyError(anchor)

    # ---------------------------------------------------------- local edits
    def local_insert(self, index: int, char: str) -> InsertOp:
        origin = None if index == 0 else self.id_at(index - 1)
        op = InsertOp(self._next_id(), origin, char)
        self.apply(op)
        return op

    def local_insert_text(self, index: int, text: str) -> List[InsertOp]:
        return [self.local_insert(index + i, ch) for i, ch in enumerate(text)]

    def local_delete(self, index: int, length: int = 1) -> List[DeleteOp]:
        ops = []
        for _ in range(length):
            op = DeleteOp(self._next_id(), self.id_at(index))
            self.apply(op)
            ops.append(op)
        return ops

    def local_format(self, start: int, end: int, mark: str, value: object) -> FormatOp:
        targets = tuple(self.id_at(i) for i in range(start, end))
        op = FormatOp(self._next_id(), targets, mark, value)
        self.apply(op)
        return op

    # -------------------------------------------------------------- applying
    def apply(self, op: Op) -> bool:
        """Apply a local or remote op. Idempotent, commutative, causal-safe."""
        ok = self._apply_one(op)
        if ok:
            self._drain_pending()
        return ok

    def _apply_one(self, op: Op) -> bool:
        if op.id in self._applied:
            return True  # duplicate delivery: no-op

        if isinstance(op, InsertOp):
            if op.origin is not None and op.origin not in self._ids:
                self._defer(op)
                return False
            self._tick(op.id)
            self._integrate(Node(op.id, op.origin, op.char))
            self._ids.add(op.id)
            self._applied.add(op.id)
            return True

        targets = op.targets if isinstance(op, FormatOp) else (op.target,)
        if any(t not in self._ids for t in targets):
            self._defer(op)
            return False

        self._tick(op.id)
        if isinstance(op, DeleteOp):
            self._node(op.target).deleted = True
        elif isinstance(op, UndeleteOp):
            self._node(op.target).deleted = False
        else:  # FormatOp - LWW per (char, mark)
            for t in op.targets:
                node = self._node(t)
                cur = node.attrs.get(op.mark)
                if cur is None or cur[1] < op.id:
                    node.attrs[op.mark] = (op.value, op.id)
        self._applied.add(op.id)
        return True

    def _defer(self, op: Op) -> None:
        if all(p.id != op.id for p in self.pending):
            self.pending.append(op)

    def _drain_pending(self) -> None:
        progress = True
        while progress and self.pending:
            progress = False
            still = []
            for op in self.pending:
                if self._apply_one(op):
                    progress = True
                else:
                    still.append(op)
            self.pending = still

    def _integrate(self, node: Node) -> None:
        """RGA integration: place after origin, skipping concurrent nodes with
        larger ids. With lamport counters this yields convergence and avoids
        interleaving of concurrent runs of text."""
        if node.origin is None:
            idx = 0
        else:
            idx = self._pos(node.origin) + 1
        while idx < len(self.nodes) and self.nodes[idx].id > node.id:
            idx += 1
        self.nodes.insert(idx, node)

    # ------------------------------------------------------------ formatting
    def spans(self) -> List[Tuple[str, Dict[str, object]]]:
        """Visible characters with resolved marks (what the renderer consumes)."""
        out = []
        for n in self.nodes:
            if n.deleted:
                continue
            attrs = {k: v for k, (v, _id) in n.attrs.items() if v not in (None, False)}
            out.append((n.char, attrs))
        return out

    def marks_in_range(self, start: int, end: int) -> Dict[str, object]:
        """Marks active across the whole selection (drives toolbar button state)."""
        spans = self.spans()[start:end]
        if not spans:
            return {}
        common: Dict[str, object] = dict(spans[0][1])
        for _ch, attrs in spans[1:]:
            common = {k: v for k, v in common.items() if attrs.get(k) == v}
        return common

"""Presence layer: multi-user cursors and selections.

Cursors are stored as anchors (character ids), not integer offsets, so they
survive concurrent remote edits without transformation. The renderer converts
anchors back to visible indices on every frame.
"""

from __future__ import annotations

from typing import Dict, Optional, Tuple

from .crdt import Document, OpId


class CursorManager:
    def __init__(self, doc: Document):
        self.doc = doc
        # user -> (anchor, head) anchors; anchor==head means a caret
        self._cursors: Dict[str, Tuple[Optional[OpId], Optional[OpId]]] = {}

    # -------- local user -> broadcastable state
    def set_cursor(self, user: str, index: int) -> Tuple[Optional[OpId], Optional[OpId]]:
        a = self._anchor_for(index)
        self._cursors[user] = (a, a)
        return self._cursors[user]

    def set_selection(self, user: str, start: int, end: int):
        self._cursors[user] = (self._anchor_for(start), self._anchor_for(end))
        return self._cursors[user]

    def _anchor_for(self, index: int) -> Optional[OpId]:
        return None if index == 0 else self.doc.id_at(index - 1)

    # -------- remote presence messages
    def receive(self, user: str, anchors) -> None:
        self._cursors[user] = tuple(anchors)

    def remove(self, user: str) -> None:
        self._cursors.pop(user, None)

    # -------- resolution for rendering
    def get_index(self, user: str) -> int:
        return self.doc.anchor_index(self._cursors[user][0])

    def get_selection(self, user: str) -> Tuple[int, int]:
        a, h = self._cursors[user]
        return self.doc.anchor_index(a), self.doc.anchor_index(h)

    def anchors(self, user: str):
        return self._cursors[user]

    def all_positions(self) -> Dict[str, Tuple[int, int]]:
        return {u: self.get_selection(u) for u in self._cursors}

"""Per-collaborator undo/redo.

Google-Docs semantics: undo only reverts *your own* operations, and it must
work even after other users' concurrent edits. We achieve this by inverting
ops against the CRDT (delete <-> undelete tombstones) rather than replaying
index-based edits, so positions never go stale.
"""

from __future__ import annotations

from typing import List, Tuple

from .crdt import DeleteOp, FormatOp, UndeleteOp


class UndoManager:
    def __init__(self, client):
        self.client = client
        self._undo: List[Tuple[str, list]] = []
        self._redo: List[Tuple[str, list]] = []

    # ------------------------------------------------------------- recording
    def record_insert(self, ids) -> None:
        self._push(("hide", list(ids)))

    def record_delete(self, ids) -> None:
        self._push(("show", list(ids)))

    def record_format(self, entries) -> None:
        # entries: [(target_id, mark, previous_value)]
        self._push(("format", list(entries)))

    def _push(self, spec) -> None:
        self._undo.append(spec)
        self._redo.clear()  # new local edit invalidates the redo branch

    # -------------------------------------------------------------- queries
    def can_undo(self) -> bool:
        return bool(self._undo)

    def can_redo(self) -> bool:
        return bool(self._redo)

    # ------------------------------------------------------------- execution
    def undo(self) -> bool:
        if not self._undo:
            return False
        self._redo.append(self._apply(self._undo.pop()))
        return True

    def redo(self) -> bool:
        if not self._redo:
            return False
        self._undo.append(self._apply(self._redo.pop()))
        return True

    def _apply(self, spec) -> Tuple[str, list]:
        """Apply an inverse spec, emit resulting ops, return spec's inverse."""
        doc = self.client.doc
        kind, data = spec
        ops = []
        if kind == "hide":
            for tid in data:
                ops.append(DeleteOp(doc._next_id(), tid))
            inverse = ("show", data)
        elif kind == "show":
            for tid in data:
                ops.append(UndeleteOp(doc._next_id(), tid))
            inverse = ("hide", data)
        else:  # format
            inv_entries = []
            for tid, mark, value in data:
                cur = doc._node(tid).attrs.get(mark)
                inv_entries.append((tid, mark, cur[0] if cur else None))
                ops.append(FormatOp(doc._next_id(), (tid,), mark, value))
            inverse = ("format", inv_entries)

        for op in ops:
            doc.apply(op)
        self.client.broadcast(ops)
        return inverse

"""Sync engine: op relay server + client with offline queue and reconnect.

Because the document is a CRDT, the "server" is a dumb ordered op log (in the
real app: WebSocket fan-out + persistence). Clients that go offline keep
editing locally, queue ops in an outbox, and on reconnect (a) flush the
outbox and (b) pull every op they missed. Convergence is guaranteed by the
CRDT regardless of delivery order or duplication.
"""

from __future__ import annotations

from typing import List, Tuple

from .crdt import Document, Op
from .cursor import CursorManager
from .undo import UndoManager


class Server:
    """Ordered, append-only op log (stand-in for the realtime backend)."""

    def __init__(self):
        self.log: List[Op] = []

    def submit(self, ops) -> int:
        self.log.extend(ops)
        return len(self.log)

    def ops_since(self, seq: int) -> Tuple[List[Op], int]:
        return list(self.log[seq:]), len(self.log)


class Client:
    """One user's editor session (document replica + presence + undo + queue)."""

    def __init__(self, site: str, server: Server):
        self.site = site
        self.server = server
        self.doc = Document(site)
        self.cursors = CursorManager(self.doc)
        self.undo_manager = UndoManager(self)
        self.connected = True
        self.outbox: List[Op] = []
        self.last_seq = 0
        self.sync()

    # --------------------------------------------------------------- editing
    def insert(self, index: int, text: str) -> None:
        ops = self.doc.local_insert_text(index, text)
        self.undo_manager.record_insert([op.id for op in ops])
        self.broadcast(ops)

    def delete(self, index: int, length: int = 1) -> None:
        ops = self.doc.local_delete(index, length)
        self.undo_manager.record_delete([op.target for op in ops])
        self.broadcast(ops)

    def format(self, start: int, end: int, mark: str, value: object = True) -> None:
        targets = [self.doc.id_at(i) for i in range(start, end)]
        entries = []
        for t in targets:
            cur = self.doc._node(t).attrs.get(mark)
            entries.append((t, mark, cur[0] if cur else None))
        op = self.doc.local_format(start, end, mark, value)
        self.undo_manager.record_format(entries)
        self.broadcast([op])

    def undo(self) -> bool:
        return self.undo_manager.undo()

    def redo(self) -> bool:
        return self.undo_manager.redo()

    # ------------------------------------------------------------- transport
    def broadcast(self, ops) -> None:
        if not ops:
            return
        if self.connected:
            self.server.submit(list(ops))
            self.sync()
        else:
            self.outbox.extend(ops)

    def sync(self) -> None:
        """Pull and apply everything we haven't seen (idempotent)."""
        if not self.connected:
            return
        ops, seq = self.server.ops_since(self.last_seq)
        for op in ops:
            self.doc.apply(op)
        self.last_seq = seq

    def disconnect(self) -> None:
        self.connected = False

    def connect(self) -> None:
        """Reconnect: flush offline edits, then catch up on missed remote ops."""
        self.connected = True
        if self.outbox:
            self.server.submit(self.outbox)
            self.outbox = []
        self.sync()

    # -------------------------------------------------------------- niceties
    @property
    def text(self) -> str:
        return self.doc.text

"""Comments anchored to text ranges.

Anchors are character ids, so comments stay attached to the right text as the
document is edited concurrently. If the entire commented range is deleted the
comment becomes orphaned (shown in the sidebar as "original text deleted").
"""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Dict, List, Optional, Tuple

from .crdt import Document, OpId


@dataclass
class Comment:
    id: str
    author: str
    text: str
    start: OpId  # first commented character
    end: OpId    # last commented character (inclusive)
    resolved: bool = False
    replies: List[Tuple[str, str]] = field(default_factory=list)  # (author, text)


class CommentManager:
    def __init__(self, doc: Document):
        self.doc = doc
        self.comments: Dict[str, Comment] = {}
        self._counter = 0

    def add(self, author: str, text: str, start_index: int, end_index: int) -> Comment:
        if end_index <= start_index:
            raise ValueError("empty comment range")
        start = self.doc.id_at(start_index)
        end = self.doc.id_at(end_index - 1)
        self._counter += 1
        c = Comment(f"c{self._counter}", author, text, start, end)
        self.comments[c.id] = c
        return c

    def reply(self, cid: str, author: str, text: str) -> None:
        self.comments[cid].replies.append((author, text))

    def resolve(self, cid: str) -> None:
        self.comments[cid].resolved = True

    def is_orphaned(self, cid: str) -> bool:
        c = self.comments[cid]
        si, ei = self.doc._pos(c.start), self.doc._pos(c.end)
        if si is None or ei is None:
            return True
        return all(self.doc.nodes[i].deleted for i in range(si, ei + 1))

    def range(self, cid: str) -> Optional[Tuple[int, int]]:
        """Current visible (start, end) of the comment, or None if orphaned."""
        if self.is_orphaned(cid):
            return None
        c = self.comments[cid]
        start = self._visible_before(c.start)
        end_before = self._visible_before(c.end)
        end_node = self.doc._node(c.end)
        end = end_before + (0 if end_node.deleted else 1)
        return (start, end)

    def anchored_text(self, cid: str) -> str:
        r = self.range(cid)
        if r is None:
            return ""
        return self.doc.text[r[0]:r[1]]

    def open_comments(self) -> List[Comment]:
        return [c for c in self.comments.values() if not c.resolved]

    def _visible_before(self, op_id: OpId) -> int:
        count = 0
        for n in self.doc.nodes:
            if n.id == op_id:
                return count
            if not n.deleted:
                count += 1
        raise KeyError(op_id)
